class _VendoredLoader(importlib.abc.Loader):

    def create_module(self, spec):
        pass

    def exec_module(self, module: 'ModuleType') -> 'None':
        source = _VENDORED_SOURCES[module.__name__]
        module.__file__ = f"{__file__}::<vendored>/{module.__name__.replace('.', '/')}.py"
        if module.__name__ in _VENDORED_PACKAGES:
            module.__path__ = [
             f"<shamela-vendored>/{module.__name__.replace('.', '/')}"]
            module.__package__ = module.__name__
        else:
            module.__package__ = module.__name__.rpartition('.')[0]
        exec(compile(source, module.__file__, 'exec'), module.__dict__)


class _VendoredFinder(importlib.abc.MetaPathFinder):

    def find_spec(self, fullname, path=None, target=None):
        if fullname not in _VENDORED_SOURCES:
            return
        spec = importlib.machinery.ModuleSpec(fullname, _LOADER, is_package=(fullname in _VENDORED_PACKAGES))
        if fullname in _VENDORED_PACKAGES:
            spec.submodule_search_locations = [
             f"<shamela-vendored>/{fullname.replace('.', '/')}"]
        return spec


